{"code":"def transform(grid):
    a=[r[:] for r in grid]; H=len(a); W=len(a[0])
    # find longest horizontal contiguous nonzero run
    best=[]
    for r in range(H):
        c=0
        while c<W:
            if a[r][c]:
                s=c
                while c<W and a[r][c]: c+=1
                if c-s>len(best): best=[(r,x,a[r][x]) for x in range(s,c)]
            else:c+=1
    if not best: return a
    sr=best[0][0]
    for _,sc,col in best:
        targets=[]
        for r in range(H):
            for c in range(W):
                if (r,c)!=(sr,sc) and a[r][c]==col and not (r==sr and any(x==c for _,x,_ in best)):
                    targets.append((r,c))
        if targets:
            # vertical to each target, horizontal connector
            for tr,tc in targets:
                lo,hi=sorted((sr,tr))
                for r in range(lo,hi+1):
                    if a[r][sc]==0:a[r][sc]=col
                lo,hi=sorted((sc,tc))
                for c in range(lo,hi+1):
                    if a[tr][c]==0:a[tr][c]=col
        else:
            for r in range(H):
                if a[r][sc]==0:a[r][sc]=col
    return a"}

